CREATE TABLE IF NOT EXISTS relationships(id uuid NOT NULL,org uuid NOT NULL,representative_id uuid NOT NULL,child_id uuid NOT NULL,reason text NOT NULL,PRIMARY KEY(org,id),FOREIGN KEY(org,representative_id) REFERENCES persons(org,id),FOREIGN KEY(org,child_id) REFERENCES persons(org,id),CHECK(representative_id<>child_id),UNIQUE(org,representative_id,child_id));
CREATE TABLE IF NOT EXISTS tariffs(id uuid NOT NULL,org uuid NOT NULL REFERENCES organizations,name text NOT NULL,visits integer NOT NULL CHECK(visits>0),price bigint NOT NULL CHECK(price>=0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),PRIMARY KEY(org,id));
CREATE TABLE IF NOT EXISTS subscriptions(id uuid NOT NULL,org uuid NOT NULL,person_id uuid NOT NULL,tariff_id uuid NOT NULL,visits integer NOT NULL CHECK(visits>0),price bigint NOT NULL CHECK(price>=0),currency text NOT NULL,expires timestamptz NOT NULL,PRIMARY KEY(org,id),FOREIGN KEY(org,person_id) REFERENCES persons(org,id),FOREIGN KEY(org,tariff_id) REFERENCES tariffs(org,id));
CREATE TABLE IF NOT EXISTS visit_reservations(org uuid NOT NULL,booking_id uuid NOT NULL,subscription_id uuid NOT NULL,state text NOT NULL CHECK(state IN ('reserved','consumed','released')),PRIMARY KEY(org,booking_id),FOREIGN KEY(org,booking_id) REFERENCES bookings(org,id),FOREIGN KEY(org,subscription_id) REFERENCES subscriptions(org,id));
CREATE TABLE IF NOT EXISTS attendance_events(id uuid NOT NULL,org uuid NOT NULL,booking_id uuid NOT NULL,status text NOT NULL CHECK(status='present'),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org,id),UNIQUE(org,booking_id),FOREIGN KEY(org,booking_id) REFERENCES bookings(org,id));
CREATE TABLE IF NOT EXISTS waitlist(id uuid NOT NULL,org uuid NOT NULL,class_id uuid NOT NULL,person_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org,id),UNIQUE(org,class_id,person_id),FOREIGN KEY(org,class_id) REFERENCES classes(org,id),FOREIGN KEY(org,person_id) REFERENCES persons(org,id));
CREATE TABLE IF NOT EXISTS charges(id uuid NOT NULL,org uuid NOT NULL,person_id uuid NOT NULL,amount bigint NOT NULL CHECK(amount>0),currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org,id),FOREIGN KEY(org,person_id) REFERENCES persons(org,id));
CREATE TABLE IF NOT EXISTS allocations(id uuid NOT NULL,org uuid NOT NULL,payment_id uuid NOT NULL,charge_id uuid NOT NULL,amount bigint NOT NULL CHECK(amount>0),PRIMARY KEY(org,id),FOREIGN KEY(org,payment_id) REFERENCES payments(org,id),FOREIGN KEY(org,charge_id) REFERENCES charges(org,id));
CREATE TABLE IF NOT EXISTS rights_confirmations(id uuid NOT NULL,org uuid NOT NULL,artwork_id uuid NOT NULL,evidence text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org,id),FOREIGN KEY(org,artwork_id) REFERENCES artworks(org,id));
